def audited_persona(prompt: str) -> str | None:
    """A card edit invalidates its reviewed summary; unknown cards use normal extraction."""
    return AUDITED_PERSONAS.get(hashlib.sha256(prompt.strip().encode('utf-8')).hexdigest())


def compact_question(key: str, question: dict) -> dict:
    """Shorten managed decision prose without changing keys or dynamic candidates."""
    instructions = question.get('instructions')
    if not isinstance(instructions, dict):
        return question
    result = {**question, 'instructions': dict(instructions)}
    if key in QUESTION_FOCUS:
        result['instructions']['focus'] = QUESTION_FOCUS[key]
    descriptions = QUESTION_CRITERIA.get(key, {})
    if key == 'length':
        from .reply_length import REPLY_LENGTH_POLICY as policy
        descriptions = {
            'brief': 'At most one sentence',
            'normal': f'1-{policy.normal_sentences} concise sentences or at most {policy.normal_list_items} short list items',
            'detailed': f'Requested depth or essential content; ordinary prose <= {policy.detailed_chars} characters. Only explicit complete-code, long-form or longer-length requests waive this cap.',
        }
    if descriptions and isinstance(question.get('criteria'), dict):
        result['criteria'] = {option: descriptions.get(option, text)
                              for option, text in question['criteria'].items()}
    return result
